mapper.select:
SELECT

FROM region r
WHERE 1 = 1

    AND CONCAT_WS(' ', r.region_code, r.sido_name, r.sigungu_name, r.dong_name, r.public_display_name)
        LIKE CONCAT('%', #{keyword}, '%')


    AND r.sido_name = #{sidoName}


    AND r.active_yn = #{activeYn}

ORDER BY r.sido_name, r.sigungu_name, r.dong_name, r.region_id
LIMIT #{limit}

SELECT

FROM region r
WHERE r.region_id = #{regionId}
